impl crate::sample::Sample for AnimatedProperty {
    fn sample(g: &mut crate::sample::Gen) -> Self {
        match g.below(2) {
            0 => Self::Transform,
            _ => Self::Opacity,
        }
    }
}

/// One keyframe's value, in `hg-interp`'s integer form.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum KeyframeValue {
    /// A transform.
    Transform {
        /// Its matrix.
        matrix: Transform,
    },
    /// An opacity, 0 to 255.
    Opacity {
        /// Its value.
        opacity: u8,
    },
}

impl Wire for KeyframeValue {
    fn encode(&self, w: &mut Writer) {
        match self {
            Self::Transform { matrix } => {
                0u32.encode(w);
                matrix.encode(w);
            }
            Self::Opacity { opacity } => {
                1u32.encode(w);
                opacity.encode(w);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        match u32::decode(r)? {
            0 => Ok(Self::Transform {
                matrix: Wire::decode(r)?,
            }),
            1 => Ok(Self::Opacity {
                opacity: Wire::decode(r)?,
            }),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        match u32::decode(r)? {
            0 => {
                <Transform as Wire>::validate(r)?;
                Ok(())
            }
            1 => {
                <u8 as Wire>::validate(r)?;
                Ok(())
            }
            _ => Err(BadMessage::UnknownTag),
        }
    }
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_min(
            hg_ipc::wire::len_add(0, <Transform as Wire>::MIN_LEN),
            hg_ipc::wire::len_add(0, <u8 as Wire>::MIN_LEN),
        ),
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_max(
            hg_ipc::wire::len_add(0, <Transform as Wire>::MAX_LEN),
            hg_ipc::wire::len_add(0, <u8 as Wire>::MAX_LEN),
        ),
    );
}

