/// A timing function, with every coefficient an integer so that a
/// sample is the same on every device (GR-D3).
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum TimingFunction {
    /// `linear`.
    Linear,
    /// `cubic-bezier`, with control points in **1/65,536** units so
    /// that the standard keywords are exact.
    CubicBezier {
        /// First control point's x.
        x1: i32,
        /// First control point's y.
        y1: i32,
        /// Second control point's x.
        x2: i32,
        /// Second control point's y.
        y2: i32,
    },
    /// `steps`.
    ///
    /// Easing Functions 1's four `<step-position>` keywords are
    /// carried as the two booleans they actually are, rather than as a
    /// four-variant enum: `jump-start` is (true, false), `jump-end`
    /// (false, true), `jump-none` (false, false) and `jump-both`
    /// (true, true). The legacy `start` and `end` keywords are
    /// resolved to `jump-start` and `jump-end` in the renderer and
    /// never reach here. Two booleans rather than an enum because
    /// GR-18 asks this format to be small and this removes a type and
    /// four variants from its published size without losing a value.
    Steps {
        /// How many steps; zero is refused.
        count: u32,
        /// Whether it jumps at the start of the interval.
        jump_at_start: bool,
        /// Whether it jumps at the end of the interval.
        jump_at_end: bool,
    },
}

impl Wire for TimingFunction {
    fn encode(&self, w: &mut Writer) {
        match self {
            Self::Linear => {
                0u32.encode(w);
            }
            Self::CubicBezier { x1, y1, x2, y2 } => {
                1u32.encode(w);
                x1.encode(w);
                y1.encode(w);
                x2.encode(w);
                y2.encode(w);
            }
            Self::Steps {
                count,
                jump_at_start,
                jump_at_end,
            } => {
                2u32.encode(w);
                count.encode(w);
                jump_at_start.encode(w);
                jump_at_end.encode(w);
            }
        }
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        match u32::decode(r)? {
            0 => Ok(Self::Linear),
            1 => Ok(Self::CubicBezier {
                x1: Wire::decode(r)?,
                y1: Wire::decode(r)?,
                x2: Wire::decode(r)?,
                y2: Wire::decode(r)?,
            }),
            2 => Ok(Self::Steps {
                count: Wire::decode(r)?,
                jump_at_start: Wire::decode(r)?,
                jump_at_end: Wire::decode(r)?,
            }),
            _ => Err(BadMessage::UnknownTag),
        }
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        match u32::decode(r)? {
            0 => Ok(()),
            1 => {
                <i32 as Wire>::validate(r)?;
                <i32 as Wire>::validate(r)?;
                <i32 as Wire>::validate(r)?;
                <i32 as Wire>::validate(r)?;
                Ok(())
            }
            2 => {
                <u32 as Wire>::validate(r)?;
                <bool as Wire>::validate(r)?;
                <bool as Wire>::validate(r)?;
                Ok(())
            }
            _ => Err(BadMessage::UnknownTag),
        }
    }
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_min(
            hg_ipc::wire::len_min(
                0,
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(0, <i32 as Wire>::MIN_LEN),
                            <i32 as Wire>::MIN_LEN,
                        ),
                        <i32 as Wire>::MIN_LEN,
                    ),
                    <i32 as Wire>::MIN_LEN,
                ),
            ),
            hg_ipc::wire::len_add(
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(0, <u32 as Wire>::MIN_LEN),
                    <bool as Wire>::MIN_LEN,
                ),
                <bool as Wire>::MIN_LEN,
            ),
        ),
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        4,
        hg_ipc::wire::len_max(
            hg_ipc::wire::len_max(
                0,
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(0, <i32 as Wire>::MAX_LEN),
                            <i32 as Wire>::MAX_LEN,
                        ),
                        <i32 as Wire>::MAX_LEN,
                    ),
                    <i32 as Wire>::MAX_LEN,
                ),
            ),
            hg_ipc::wire::len_add(
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(0, <u32 as Wire>::MAX_LEN),
                    <bool as Wire>::MAX_LEN,
                ),
                <bool as Wire>::MAX_LEN,
            ),
        ),
    );
}

