/// One keyframe.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Keyframe {
    /// Its progress offset, in **1/65,536** of the animation, so 0 is
    /// the start and 65,536 the end.
    pub offset: u32,
    /// Its value.
    pub value: KeyframeValue,
    /// How it eases to the next keyframe.
    pub easing: TimingFunction,
}

impl Wire for Keyframe {
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        hg_ipc::wire::len_add(
            hg_ipc::wire::len_add(0, <u32 as Wire>::MIN_LEN),
            <KeyframeValue as Wire>::MIN_LEN,
        ),
        <TimingFunction as Wire>::MIN_LEN,
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        hg_ipc::wire::len_add(
            hg_ipc::wire::len_add(0, <u32 as Wire>::MAX_LEN),
            <KeyframeValue as Wire>::MAX_LEN,
        ),
        <TimingFunction as Wire>::MAX_LEN,
    );
    fn encode(&self, w: &mut Writer) {
        self.offset.encode(w);
        self.value.encode(w);
        self.easing.encode(w);
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        Ok(Self {
            offset: Wire::decode(r)?,
            value: Wire::decode(r)?,
            easing: Wire::decode(r)?,
        })
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        <u32 as Wire>::validate(r)?;
        <KeyframeValue as Wire>::validate(r)?;
        <TimingFunction as Wire>::validate(r)?;
        Ok(())
    }
}

