/// The animation spec's **bounded record** (its 6.5), which replaced
/// the prose list in 6.8 and 6.28 on 20 October 2026: id, property,
/// keyframes in `hg-interp`'s integer form, timing function, start
/// time at "ready", class and bounds. The compositor samples only at
/// the document's recorded frame tick (AN-D3).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Animation {
    /// Its id.
    pub id: u64,
    /// The property-tree node it drives.
    pub target: u32,
    /// Which property.
    pub property: AnimatedProperty,
    /// Its start time on the compositor timeline, in microseconds,
    /// fixed at "ready".
    pub start_time_us: i64,
    /// Its duration in microseconds.
    pub duration_us: i64,
    /// The bounds the record declares, which the compositor uses to
    /// damage without reading content.
    pub bounds: Rect,
    /// Its keyframes, at least 2 and at most 64†.
    pub keyframes: hg_ipc::BoundedVec<Keyframe, 64>,
}

impl Wire for Animation {
    const MIN_LEN: usize = hg_ipc::wire::len_add(
        hg_ipc::wire::len_add(
            hg_ipc::wire::len_add(
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(0, <u64 as Wire>::MIN_LEN),
                            <u32 as Wire>::MIN_LEN,
                        ),
                        <AnimatedProperty as Wire>::MIN_LEN,
                    ),
                    <i64 as Wire>::MIN_LEN,
                ),
                <i64 as Wire>::MIN_LEN,
            ),
            <Rect as Wire>::MIN_LEN,
        ),
        <hg_ipc::BoundedVec<Keyframe, 64> as Wire>::MIN_LEN,
    );
    const MAX_LEN: usize = hg_ipc::wire::len_add(
        hg_ipc::wire::len_add(
            hg_ipc::wire::len_add(
                hg_ipc::wire::len_add(
                    hg_ipc::wire::len_add(
                        hg_ipc::wire::len_add(
                            hg_ipc::wire::len_add(0, <u64 as Wire>::MAX_LEN),
                            <u32 as Wire>::MAX_LEN,
                        ),
                        <AnimatedProperty as Wire>::MAX_LEN,
                    ),
                    <i64 as Wire>::MAX_LEN,
                ),
                <i64 as Wire>::MAX_LEN,
            ),
            <Rect as Wire>::MAX_LEN,
        ),
        <hg_ipc::BoundedVec<Keyframe, 64> as Wire>::MAX_LEN,
    );
    fn encode(&self, w: &mut Writer) {
        self.id.encode(w);
        self.target.encode(w);
        self.property.encode(w);
        self.start_time_us.encode(w);
        self.duration_us.encode(w);
        self.bounds.encode(w);
        self.keyframes.encode(w);
    }
    fn decode(r: &mut Reader<'_>) -> Result<Self, BadMessage> {
        Ok(Self {
            id: Wire::decode(r)?,
            target: Wire::decode(r)?,
            property: Wire::decode(r)?,
            start_time_us: Wire::decode(r)?,
            duration_us: Wire::decode(r)?,
            bounds: Wire::decode(r)?,
            keyframes: Wire::decode(r)?,
        })
    }
    fn validate(r: &mut Reader<'_>) -> Result<(), BadMessage> {
        <u64 as Wire>::validate(r)?;
        <u32 as Wire>::validate(r)?;
        <AnimatedProperty as Wire>::validate(r)?;
        <i64 as Wire>::validate(r)?;
        <i64 as Wire>::validate(r)?;
        <Rect as Wire>::validate(r)?;
        <hg_ipc::BoundedVec<Keyframe, 64> as Wire>::validate(r)?;
        Ok(())
    }
}

